css:
.card {
  --border: 4px;
  --rounded: 16px;
  --quantity: 12;
  --w-card: 450px;
  --h-card: 400px;
  margin: 0;
  width: var(--w-card);
  height: var(--h-card);
  max-width: 80%;
  max-height: 80%;
  border-radius: var(--rounded);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  padding: var(--border);
  /* box-shadow: 0px 0px 16px 0px #cfecff; */
}
.card::before,
.card::after {
  content: "";
  z-index: -1;
  position: absolute;
  will-change: auto;
  --size: calc(100%);
  --size-old: calc(100% - calc(var(--border) * 2));
  width: var(--size);
  height: var(--size);
  min-width: var(--size);
  min-height: var(--size);
  max-width: var(--size);
  max-height: var(--size);
  border-radius: var(--rounded);
  background-size: 400% 400%;
  animation: bg-spin 3s linear 0s infinite normal none running;
  background-image: radial-gradient(
      circle farthest-side at 0 100%,
      #00ccb1,
      transparent
    ),
    radial-gradient(circle farthest-side at 100% 0, #5ddcff, transparent),
    radial-gradient(circle farthest-side at 100% 100%, #3c67e3, transparent),
    radial-gradient(circle farthest-side at 0 0, #4e00c2, #0000);
}

.card::after {
  transition-property: color, background-color, border-color,
    text-decoration-color, fill, stroke, opacity, box-shadow, transform, filter,
    backdrop-filter;
  transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
  transition-duration: 0.5s;
  animation-delay: 0.5s;
  filter: blur(24px);
  opacity: 0.7;
}
@keyframes bg-spin {
  25% {
    background-position: right 20% bottom 40%;
  }
  75% {
    background-position: left 45% top 20%;
  }
}

.points_wrapper {
  position: absolute;
  overflow: hidden;
  width: calc(100% - (var(--border) * 4));
  height: calc(100% - (var(--border) * 4));
  border-radius: calc(var(--rounded) - 4px);
  pointer-events: none;
  z-index: 80;
}

.points_wrapper .point {
  --sz-point: 4px;
  top: -8px;
  position: absolute;
  animation: floating-points infinite ease-in-out;
  pointer-events: none;
  width: var(--sz-point);
  height: var(--sz-point);
  background-color: #5ddcff;
  border-radius: 9999px;
}
@keyframes floating-points {
  0% {
    transform: translate(0, 0);
  }
  95% {
    opacity: 0;
  }
  100% {
    opacity: 0;
    transform: translate(calc(var(--h-card) / 1.75), calc(var(--h-card) / 1.5));
  }
}
.points_wrapper .point:nth-child(1) {
  left: 10%;
  opacity: 1;
  animation-duration: 2.35s;
  animation-delay: 0.2s;
}
.points_wrapper .point:nth-child(2) {
  left: 30%;
  opacity: 0.7;
  animation-duration: 2.5s;
  animation-delay: 0.5s;
}
.points_wrapper .point:nth-child(3) {
  left: 25%;
  opacity: 0.8;
  animation-duration: 2.2s;
  animation-delay: 0.1s;
}
.points_wrapper .point:nth-child(4) {
  left: 44%;
  opacity: 0.6;
  animation-duration: 2.05s;
}
.points_wrapper .point:nth-child(5) {
  left: 50%;
  opacity: 1;
  animation-duration: 1.9s;
}
.points_wrapper .point:nth-child(6) {
  left: 75%;
  opacity: 0.5;
  animation-duration: 1.5s;
  animation-delay: 1.5s;
}
.points_wrapper .point:nth-child(7) {
  left: 88%;
  opacity: 0.9;
  animation-duration: 2.2s;
  animation-delay: 0.2s;
}
.points_wrapper .point:nth-child(8) {
  left: 58%;
  opacity: 0.8;
  animation-duration: 2.25s;
  animation-delay: 0.2s;
}
.points_wrapper .point:nth-child(9) {
  left: 98%;
  opacity: 0.6;
  animation-duration: 2.6s;
  animation-delay: 0.1s;
}
.points_wrapper .point:nth-child(10) {
  left: 65%;
  opacity: 1;
  animation-duration: 2.5s;
  animation-delay: 0.2s;
}

.content {
  position: absolute;
  width: calc(100% - (var(--border) * 4));
  height: calc(100% - (var(--border) * 4));
  border-radius: calc(var(--rounded) - 4px);
  overflow: hidden;
  z-index: 7;
  background-color: #191c29;
}
